<?php
namespace App\Http\Controllers; use App\Models\Penerima; use App\Models\KategoriBantuan; use App\Models\RiwayatBantuan; use App\Support\WilayahScope;
class DashboardController extends Controller { public function index(){ $u=auth()->user(); if($u->peran==='masyarakat'){ $p=Penerima::where('id_user',$u->id_user)->with('riwayat.jenis.kategori')->first(); return view('masyarakat.dashboard',compact('p')); } $q=Penerima::query(); if($u->id_wilayah)$q->whereIn('id_wilayah',WilayahScope::ids($u->id_wilayah)); $stats=['total'=>(clone $q)->count(),'diajukan'=>(clone $q)->where('status','diajukan')->count(),'terverifikasi'=>(clone $q)->where('status','terverifikasi')->count(),'ditolak'=>(clone $q)->where('status','ditolak')->count()]; $recent=(clone $q)->latest()->take(8)->get();$kategori=KategoriBantuan::withCount('jenis')->get();return view('admin.dashboard',compact('stats','recent','kategori')); } }
